"use strict";(self.webpackChunkdocumentation=self.webpackChunkdocumentation||[]).push([[849],{86164:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/docs/intro/","label":"\ud83d\udcd6 Overview","docId":"intro/index","unlisted":false},{"type":"category","label":"\ud83d\ude80 Getting Started","collapsed":false,"items":[{"type":"link","href":"/docs/intro/getting-started-no-key","label":"\ud83d\udd11 Without an API Key","docId":"intro/getting-started-no-key","unlisted":false}],"collapsible":true,"href":"/docs/intro/getting-started"},{"type":"category","label":"\ud83e\uddf1 Core Concepts","collapsed":false,"items":[{"type":"link","href":"/docs/sqrl-language","label":"\ud83d\udcda SQRL Language","docId":"sqrl-language","unlisted":false},{"type":"link","href":"/docs/connectors","label":"\ud83d\udd0c Source & Sink Connectors","docId":"connectors","unlisted":false},{"type":"link","href":"/docs/interface","label":"\ud83d\udd17 Interface","docId":"interface","unlisted":false},{"type":"category","label":"\u2699\ufe0f Configuration","items":[{"type":"link","href":"/docs/configuration-engine/flink","label":"Flink Engine","docId":"configuration-engine/flink","unlisted":false},{"type":"link","href":"/docs/configuration-engine/kafka","label":"Kafka Engine","docId":"configuration-engine/kafka","unlisted":false},{"type":"link","href":"/docs/configuration-engine/vertx","label":"Vert.x Engine","docId":"configuration-engine/vertx","unlisted":false},{"type":"link","href":"/docs/configuration-engine/postgres","label":"PostgreSQL Engine","docId":"configuration-engine/postgres","unlisted":false},{"type":"link","href":"/docs/configuration-engine/iceberg","label":"Iceberg Engine","docId":"configuration-engine/iceberg","unlisted":false},{"type":"link","href":"/docs/configuration-engine/iceberg-query","label":"Iceberg Query Engines","docId":"configuration-engine/iceberg-query","unlisted":false},{"type":"link","href":"/docs/configuration-default","label":"Default Configuration","docId":"configuration-default","unlisted":false},{"type":"link","href":"/docs/configuration-engine/cloud-deployment","label":"Cloud Deployment","docId":"configuration-engine/cloud-deployment","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/configuration"},{"type":"category","label":"\ud83d\udd22 Functions","items":[{"type":"link","href":"/docs/functions-system-generated","label":"System Functions","docId":"functions-system-generated","unlisted":false},{"type":"link","href":"/docs/functions-library-generated","label":"Library Functions","docId":"functions-library-generated","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/functions"},{"type":"category","label":"\ud83d\udee0\ufe0f Compiler","items":[{"type":"link","href":"/docs/compiler-output","label":"Compiler Output","docId":"compiler-output","unlisted":false},{"type":"link","href":"/docs/deployment","label":"Deployment","docId":"deployment","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/docs/compiler"},{"type":"link","href":"/docs/intro/concepts","label":"\ud83e\udde0 Streaming Concepts","docId":"intro/concepts","unlisted":false}],"collapsible":true},{"type":"link","href":"/docs/intro/examples","label":"\ud83c\udf93 Examples","docId":"intro/examples","unlisted":false},{"type":"link","href":"/docs/intro/faq","label":"\u2753 FAQ","docId":"intro/faq","unlisted":false},{"type":"category","label":"\ud83e\uddea Advanced","items":[{"type":"link","href":"/docs/deepdive","label":"\ud83d\udc69\u200d\ud83d\udcbb How DataSQRL Works","docId":"deepdive","unlisted":false},{"type":"link","href":"/docs/compatibility","label":"\ud83d\udd04 Compatibility","docId":"compatibility","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"compatibility":{"id":"compatibility","title":"Version Compatibility","description":"DataSQRL builds on top of Flink and the Flink connector ecosystem.","sidebar":"tutorialSidebar"},"compiler":{"id":"compiler","title":"DataSQRL Command","description":"The DataSQRL command initializes, compiles, runs, and tests SQRL projects.","sidebar":"tutorialSidebar"},"compiler-output":{"id":"compiler-output","title":"Compiler Output","description":"The compile command writes two kinds of output. Compilation outputs in the build folder describe the data model and the pipeline the compiler planned. Deployment outputs in build/deploy/plan are the artifacts each engine executes. The run and test commands produce the same output before they execute the pipeline.","sidebar":"tutorialSidebar"},"configuration":{"id":"configuration","title":"DataSQRL Configuration (package.json file)","description":"DataSQRL projects are configured with one or more package.json files which are merged in the order they are provided to the DataSQRL command \u2013 latter files override fields in earlier ones, objects are deep-merged*, and array values are replaced wholesale. User provided configuration files are merged on top of the default package.json.","sidebar":"tutorialSidebar"},"configuration-default":{"id":"configuration-default","title":"Default DataSQRL package.json Configuration","description":"The following is the default configuration file that user provided configuration files are merged on top of. It provides the default values for all configuration options.","sidebar":"tutorialSidebar"},"configuration-engine/cloud-deployment":{"id":"configuration-engine/cloud-deployment","title":"DataSQRL Cloud Deployment Configuration","description":"Configures the cloud resources for each engine when deploying pipelines to DataSQRL Cloud. Deployment settings are configured under the deployment field within each engine\'s configuration.","sidebar":"tutorialSidebar"},"configuration-engine/flink":{"id":"configuration-engine/flink","title":"Flink Engine Configuration","description":"Apache Flink is a streaming and batch data processor that serves as the core data processing engine in DataSQRL pipelines.","sidebar":"tutorialSidebar"},"configuration-engine/iceberg":{"id":"configuration-engine/iceberg","title":"Iceberg Engine Configuration","description":"Apache Iceberg is an analytic database format that provides ACID transactions, schema evolution, and time travel capabilities for large analytic datasets.","sidebar":"tutorialSidebar"},"configuration-engine/iceberg-query":{"id":"configuration-engine/iceberg-query","title":"Iceberg Query Engine Configurations","description":"Apache Iceberg stores analytic data but does not execute queries. Enable an Iceberg query engine alongside iceberg to create and query Iceberg tables.","sidebar":"tutorialSidebar"},"configuration-engine/kafka":{"id":"configuration-engine/kafka","title":"Kafka Engine Configuration","description":"Apache Kafka is a streaming data platform that serves as the log engine in DataSQRL pipelines for handling data streams and event logs.","sidebar":"tutorialSidebar"},"configuration-engine/postgres":{"id":"configuration-engine/postgres","title":"PostgreSQL Engine Configuration","description":"PostgreSQL is a realtime database that stores the materialized views and tables generated by your DataSQRL pipeline for low-latency querying.","sidebar":"tutorialSidebar"},"configuration-engine/vertx":{"id":"configuration-engine/vertx","title":"Vert.x Engine Configuration","description":"Eclipse Vert.x is a reactive server framework that serves as the GraphQL API server, routing queries to the backing database/log engines.","sidebar":"tutorialSidebar"},"connectors":{"id":"connectors","title":"Connecting External Data Sources and Sinks","description":"Use CREATE TABLE statements to connect external data sources and sinks with your SQRL script using the WITH clause to provide connector configuration.","sidebar":"tutorialSidebar"},"deepdive":{"id":"deepdive","title":"Deep Dive: How DataSQRL Works","description":"The DataSQRL compile executes the following steps:","sidebar":"tutorialSidebar"},"deployment":{"id":"deployment","title":"Deployment","description":"The compiler generates all deployment assets for a pipeline in build/deploy/plan: Flink plans, Kafka topic definitions, database schemas, and the API server model (see Compiler Output). This page gives an overview of how to deploy those assets to production.","sidebar":"tutorialSidebar"},"functions":{"id":"functions","title":"Functions","description":"System Functions","sidebar":"tutorialSidebar"},"functions-library-generated":{"id":"functions-library-generated","title":"Library Functions","description":"DataSQRL provides extended library functions that can be imported into your SQRL scripts. These functions offer specialized capabilities for mathematical operations, data processing, AI integration, and external system connectivity.","sidebar":"tutorialSidebar"},"functions-system-generated":{"id":"functions-system-generated","title":"System Functions","description":"DataSQRL provides built-in system functions that are available in all SQRL scripts. These functions are grouped by functionality and provide essential operations for data processing, JSON manipulation, vector operations, and text processing.","sidebar":"tutorialSidebar"},"interface":{"id":"interface","title":"Designing the Interface","description":"Based on the SQRL script, DataSQRL generates the interface for the compiled data pipeline. DataSQRL supports the following interfaces:","sidebar":"tutorialSidebar"},"intro/concepts":{"id":"intro/concepts","title":"Key DataSQRL Concepts","description":"This document explains some of the key concepts in streaming data processing.","sidebar":"tutorialSidebar"},"intro/examples":{"id":"intro/examples","title":"Examples Gallery","description":"A gallery of what you can build with the DataSQRL data engineering harness, from a data product suite for a retail bank to small, self-contained pipelines across a range of use cases. Every example is open source. You can read the SQL, run it locally, and run its tests.","sidebar":"tutorialSidebar"},"intro/faq":{"id":"intro/faq","title":"Frequently Asked Questions","description":"Why do I need DataSQRL in addition to my coding agent?","sidebar":"tutorialSidebar"},"intro/getting-started":{"id":"intro/getting-started","title":"Getting Started with DataSQRL","description":"Basic DataSQRL Agent","sidebar":"tutorialSidebar"},"intro/getting-started-no-key":{"id":"intro/getting-started-no-key","title":"Getting Started with DataSQRL","description":"This tutorial demonstrates how the DataSQRL data engineering harness works without an LLM API key. That means we won\'t be running an agent that autonomously uses the harness to build data projects, but walk an agent through the steps and use the harness to ensure correct, safe, and easy to understand results.","sidebar":"tutorialSidebar"},"intro/index":{"id":"intro/index","title":"DataSQRL Documentation","description":"DataSQRL is an open-source data engineering harness for building data engineering agents designed around human control, correctness, and safety. It extends your coding agent (Claude Code, Codex, OpenCode, Pi, and others) with a SQL compiler, a validator, an event-time simulator, and your own skills and policies. The result is an agent you can trust with data pipelines, batch jobs, data APIs (REST, GraphQL, MCP), data products, and operational data.","sidebar":"tutorialSidebar"},"sqrl-language":{"id":"sqrl-language","title":"SQRL Language Specification","description":"SQRL is an extension of Flink SQL that adds support for table functions and convenience syntax to build reactive data processing and serving applications.","sidebar":"tutorialSidebar"},"stdlib-docs/CLAUDE":{"id":"stdlib-docs/CLAUDE","title":"CLAUDE.md","description":"This file provides guidance to Claude Code (claude.ai/code) when working with code in this repository."},"stdlib-docs/RELEASE":{"id":"stdlib-docs/RELEASE","title":"Release Process for Flink SQL Runner","description":"Releasing a new version of flink-sql-runner is simple and fully automated via GitHub Actions."}}}}')}}]);